    function testRegression_property() public {
        c.initialize();

        c.updateRoundImplementation(payable(address(0x1)));
        c.updateAlloSettings(address(0x2));



        bool ok = false;
        try c.transferOwnership(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "transferOwnership to zero should revert");
    }
